const item = $input.item;
const content = item.json.content || {};
const event = content.event;
let msg = "";

// Helpers para formatação de dados
function formatTS(ts) {
  if (!ts) return "N/A";
  try {
    const d = new Date(ts);
    if (isNaN(d.getTime())) return ts;
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    const hours = String(d.getHours()).padStart(2, '0');
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const seconds = String(d.getSeconds()).padStart(2, '0');
    return `${day}/${month}/${year} ${hours}:${minutes}:${seconds}`;
  } catch {
    return ts;
  }
}

function cleanIps(ipStr) {
  if (!ipStr) return "N/A";
  return ipStr.replace(/[\\[\\]']/g, "").split(",").map(s => s.trim()).join(", ");
}

if (event === "incident_opened") {
  msg = `🚨 <b>[ALERTA DE INCIDENTE NOC]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço:</b> <code>${content.host_address}</code>\n` +
        `🛠️ <b>Serviço:</b> <code>${content.check_used}</code>\n` +
        `⚠️ <b>Falha:</b> <i>${content.reason}</i>\n\n` +
        `⏱️ <b>Início:</b> ${formatTS(content.started_time)}\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🔴 Status: <b>OFFLINE</b>`;
} else if (event === "incident_closed") {
  const duration = content.duration_seconds || 0;
  const hours = Math.floor(duration / 3600);
  const minutes = Math.floor((duration % 3600) / 60);
  const seconds = duration % 60;
  const durationStr = `${hours}h ${minutes}m ${seconds}s`;

  msg = `✅ <b>[INCIDENTE RESOLVIDO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço:</b> <code>${content.host_address}</code>\n` +
        `⏱️ <b>Duração:</b> <code>${durationStr}</code>\n\n` +
        `🟢 Status: <b>ONLINE (Serviço normalizado)</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⏱️ <b>Horário:</b> ${formatTS(content.ended_time)}`;
} else if (event === "dns_change") {
  msg = `🔄 <b>[ALTERAÇÃO DE IP NO DNS]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Hostname:</b> <code>${content.host_address}</code>\n\n` +
        `❌ <b>IP Anterior:</b> <code>${content.old_ip}</code>\n` +
        `✅ <b>Novo IP:</b> <code>${cleanIps(content.new_ip)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⏱️ <b>Detectado em:</b> ${formatTS(content.timestamp)}`;
} else if (event === "dns_ttl_low") {
  msg = `⚠️ <b>[AVISO DE DNS: TTL BAIXO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Hostname:</b> <code>${content.host_address}</code>\n` +
        `⏱️ <b>Valor do TTL:</b> <code>${content.ttl}s</code> (Crítico)\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⏱️ <b>Horário:</b> ${formatTS(content.timestamp)}`;
} else if (event === "health_critical") {
  msg = `❤️‍🩹 <b>[SAÚDE DO DISPOSITIVO EM CRÍTICO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço:</b> <code>${content.host_address}</code>\n` +
        `📈 <b>Score de Saúde:</b> <code>${content.health_score}%</code>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⚠️ <i>Dispositivo operando em estado de alerta crítico.</i>\n` +
        `⏱️ <b>Horário:</b> ${formatTS(content.timestamp)}`;
} else if (event === "preventive_alert") {
  msg = `⚠️ <b>[ALERTA PREVENTIVO - MÉTRICAS]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço:</b> <code>${content.host_address}</code>\n` +
        `🚨 <b>Métrica:</b> <code>${content.condition}</code>\n\n` +
        `📋 <b>Detalhes:</b>\n<code>${content.details}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⏱️ <b>Horário:</b> ${formatTS(content.timestamp)}`;
} else if (event === "failure_confirmed") {
  msg = `❌ <b>[FALHA CONFIRMADA]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço:</b> <code>${content.host_address}</code>\n` +
        `🛠️ <b>Checagem Usada:</b> <code>${content.check_used}</code>\n` +
        `🔄 <b>Estado:</b> <code>${content.old_status} ➔ ${content.new_status}</code>\n` +
        `📉 <b>Falhas Consecutivas:</b> ${content.fail_streak}\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⏱️ <b>Horário:</b> ${formatTS(content.timestamp)}`;
} else if (event === "recovery") {
  msg = `🟢 <b>[DISPOSITIVO RECUPERADO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Host:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço:</b> <code>${content.host_address}</code>\n` +
        `🔄 <b>Estado:</b> <code>${content.old_status} ➔ UP</code>\n` +
        `━━━━━━━━━━━━━━━━━━━\n` +
        `⏱️ <b>Horário:</b> ${formatTS(content.timestamp)}`;
} else {
  msg = `✉️ <b>[NOTIFICAÇÃO NETSPOT]</b>\n\n` +
        `${content.message || JSON.stringify(item.json)}`;
}

item.json.formatted_message = msg;
return item;
